export type TranslationKey = keyof typeof messages.vi;

export function translate(language: AppLanguage, key: TranslationKey, params?: Record<string, string | number>): string {
  let value: string = messages[language][key] ?? messages.vi[key];
  for (const [name, replacement] of Object.entries(params ?? {})) value = value.replace(`{${name}}`, String(replacement));
  return value;
}

export function useI18n() {
  const language = useAppStore((state) => state.language);
  return { language, t: (key: TranslationKey, params?: Record<string, string | number>) => translate(language, key, params) };
}
